args<-commandArgs(TRUE);o<-normalizePath(args[1]);.libPaths(c(file.path(o,'r_library'),.libPaths()))
library(ggplot2);library(ggalluvial);library(patchwork);library(dplyr);library(tidyr);library(grid)
a<-read.delim(file.path(o,'data/age_display_records.tsv'));b<-read.delim(file.path(o,'data/Figure6B_records.tsv'));cc<-read.delim(file.path(o,'data/Figure6C_records.tsv'));d<-read.delim(file.path(o,'data/age_COG_display.tsv'))
labels<-c(J='Translation',A='RNA processing',K='Transcription',L='Replication',B='Chromatin structure',D='Cell cycle',Y='Nuclear structure',V='Defense mechanisms',T='Signal transduction',M='Cell wall/membrane',N='Cell motility',Z='Cytoskeleton',W='Extracellular structures',U='Intracellular trafficking',O='Posttranslational modification',C='Energy production',G='Carbohydrate transport',E='Amino acid transport',F='Nucleotide transport',H='Coenzyme transport',I='Lipid transport',P='Inorganic ion transport',Q='Secondary metabolites',R='General function prediction',S='Function unknown')
eras<-c('Precambrian','Paleozoic','Mesozoic','Cenozoic');era_axis<-c('Precambrian','Paleozoic','Mesozoic','Cenozoic')
th<-theme_classic(base_size=9,base_family='Arial')+theme(axis.text=element_text(size=8.5,color='black'),axis.title=element_text(size=9,face='bold'),plot.title=element_text(size=9.5,face='bold'),legend.text=element_text(size=8.5),legend.title=element_text(size=8.5,face='bold'),plot.margin=margin(4,5,4,5),plot.tag=element_text(size=12,face='bold'),panel.grid.major.y=element_line(color='grey90',linetype='dashed',linewidth=.25))
savep<-function(p,n,w,h){f<-file.path(o,'figures',n);ggsave(paste0(f,'.pdf'),p,width=w,height=h,units='mm',device=cairo_pdf,family='Arial',bg='white');ggsave(paste0(f,'.svg'),p,width=w,height=h,units='mm',device=svglite::svglite,fix_text_size=FALSE,bg='white');ggsave(paste0(f,'.png'),p,width=w,height=h,units='mm',dpi=400,type='cairo',bg='white')}
densitypanel<-function(z,tag){
 er<-data.frame(era=c('Cenozoic','Mesozoic','Paleozoic','Precambrian'),start=c(0,66,252,541),end=c(66,252,541,1500),color=c('#FAD7A1','#A9DFBF','#AED6F1','#E5E7E9'))
 er$x<-c(23,145,382,1000);er$lab<-c('Cenozoic','Mesozoic','Paleozoic','Precambrian')
 p<-ggplot()+geom_rect(data=er,aes(xmin=start,xmax=end,ymin=0,ymax=Inf,fill=era),alpha=.4)+scale_fill_manual(values=setNames(er$color,er$era))+geom_density(data=z,aes(Age_MYA),fill='#2C3E50',color='#1A252F',alpha=.6,linewidth=.55,adjust=1)+geom_rug(data=z,aes(Age_MYA),color='#E74C3C',alpha=.45,sides='b',length=unit(.03,'npc'))+scale_x_reverse(breaks=c(0,66,252,541,1000,1500),limits=c(1500,0),expand=c(0,0))+scale_y_continuous(expand=expansion(mult=c(0,.25)))+labs(x='Minimum HGT age (Ma)',y='Density',tag=tag)+th+theme(legend.position='none',axis.text.x=element_text(angle=45,hjust=1),plot.margin=margin(5,7,2,5))
 # Era names are kept above the density; young periods use staggered labels to remain legible.
 maxy<-max(density(z$Age_MYA)$y)
 p+annotate('text',x=1100,y=maxy*1.20,label='Precambrian',size=3,family='Arial',fontface='bold',color='#34495E')+annotate('text',x=398,y=maxy*1.20,label='Paleozoic',size=3,family='Arial',fontface='bold',color='#34495E')+annotate('text',x=167,y=maxy*1.20,label='Mesozoic',size=3,family='Arial',fontface='bold',color='#34495E')+annotate('text',x=8,y=maxy*.96,label='Cenozoic',hjust=1,size=3,family='Arial',fontface='bold',color='#34495E')
}
scatter<-function(z,col,tag,gc=FALSE){
 z$y<-z[[col]];p<-ggplot(z,aes(Age_MYA,y))
 if(gc){p<-p+geom_hline(yintercept=0,linetype='dashed',linewidth=.4)+geom_point(aes(fill=Data_type),alpha=.55,color='grey25',shape=21,size=.8,stroke=.15)+scale_fill_manual(values=c(Protein='#2E5077',Nucleotide='#4DA1A9'),name='Sequence type')}
 else p<-p+geom_point(alpha=.55,color='grey25',shape=21,size=.8,stroke=.15)
 rho<-cor(z$Age_MYA,z$y,method='spearman');annot<-sprintf('rho = %.3f; n = %s',rho,format(nrow(z),big.mark=','))
 p+geom_smooth(method='loess',formula=y~x,color='#E74C3C',fill='#FADBD8',alpha=.35,linewidth=.65,se=TRUE)+annotate('text',x=Inf,y=Inf,label=annot,hjust=1.03,vjust=1.3,size=3,family='Arial')+labs(x='Minimum HGT age (Ma)',y=if(gc)'GC difference (percentage points)' else 'Pairwise Ka/Ks',tag=tag)+th+theme(legend.position='top',legend.key.height=unit(3,'mm'),legend.key.width=unit(3,'mm'),legend.margin=margin(0,0,0,0))
}
functional<-function(panel,tags){
 z<-d[d$panel==panel,];z$era<-factor(z$era,levels=eras);z$full<-unname(labels[z$COG]);lev<-sort(unique(z$full));z$full<-factor(z$full,levels=lev)
 p1<-ggplot(z,aes(x=era,y=percentage,fill=full,stratum=full,alluvium=full))+geom_alluvium(alpha=.4,width=.25,color='white',linewidth=.1)+geom_stratum(width=.25,color='white',linewidth=.3)+scale_fill_viridis_d(option='turbo',name='COG functional category',labels=setNames(paste0(names(labels)[match(lev,unname(labels))],'  ',lev),lev),guide=guide_legend(ncol=1))+scale_y_continuous(breaks=c(0,25,50,75,100),expand=c(0,0))+labs(x='Minimum-age category',y='Relative proportion (%)',tag=tags[1])+th+theme(panel.grid.major.y=element_line(color='grey90',linewidth=.2),axis.text.x=element_text(angle=45,hjust=1),legend.position='right',legend.key.height=unit(3.1,'mm'),legend.key.width=unit(2.5,'mm'),legend.spacing.y=unit(0,'mm'),legend.margin=margin(0,0,0,0),legend.text=element_text(size=8.5),legend.title=element_text(size=8.5),plot.margin=margin(4,0,4,5))
 z$heatcat<-factor(z$full,levels=rev(lev));codes<-setNames(names(labels)[match(lev,unname(labels))],lev)
 p2<-ggplot(z,aes(era,heatcat,fill=Pearson_residual))+geom_tile(color='white',linewidth=.25)+geom_text(aes(label=sprintf('%.1f',Pearson_residual)),size=3,family='Arial',color='black')+scale_y_discrete(labels=codes)+scale_fill_gradient2(low='#377EB8',mid='white',high='#E41A1C',midpoint=0,name='Pearson\nresidual')+labs(x='Minimum-age category',y='COG category',tag=tags[2])+th+theme(panel.grid=element_blank(),axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(angle=45,hjust=1),axis.text.y=element_text(size=8.5),legend.position='right',legend.key.width=unit(2.5,'mm'),legend.key.height=unit(4,'mm'),legend.text=element_text(size=8.5),legend.title=element_text(size=8.5),plot.margin=margin(4,1,4,2))
 list(p1,p2)
}
f<-functional('Figure6',c('D','E'))
# Original row structure: A full width; B/C; D/E. Legend labels are shared through COG codes.
p<-(densitypanel(a,'A') / (scatter(b,'omega','B')|scatter(cc,'HGT_diff','C',TRUE)) / (f[[1]]|f[[2]]))+plot_layout(heights=c(.78,1.13,1.85))
savep(p,'Figure6',180,215)
for(n in c('FigureS4','FigureS5')){
 group<-if(n=='FigureS4')'Microbial eukaryotic parasites' else 'Metazoan parasites';f<-functional(n,c('B','C'));p<-densitypanel(a[a$group==group,],'A')/(f[[1]]|f[[2]])+plot_layout(heights=c(.82,1.95));savep(p,n,180,160)
}
# Restore original Figure2 A/B facets, palette, outliers, and relative alignment scales.
q<-read.delim(file.path(o,'data/Figure2CD_existing_components.tsv'));ab<-read.delim(file.path(o,'data/Figure2A_existing_counts.tsv'));m<-read.delim(file.path(o,'data/Figure2B_existing_records.tsv'))
cols<-c('Microbial eukaryotes'='#2E86AB','Metazoan parasites'='#F18F01');group<-function(x)ifelse(x=='Metazoa','Metazoan parasites','Microbial eukaryotes')
ab$Group<-factor(group(ab$group),levels=names(cols));al<-bind_rows(data.frame(Group=ab$Group,Metric='Avg. HGT per species',Value=ab$mean),data.frame(Group=ab$Group,Metric='Total HGT candidates',Value=ab$records));al$Metric<-factor(al$Metric,levels=c('Avg. HGT per species','Total HGT candidates'))
facettheme<-theme_bw(base_size=9,base_family='Arial')+theme(axis.text=element_text(size=8.5,color='black'),axis.title=element_text(size=9,face='bold'),plot.title=element_text(size=9.5,face='bold',hjust=.5),strip.text=element_text(size=9,face='bold'),panel.grid=element_blank(),legend.position='none',plot.tag=element_text(size=12,face='bold'),plot.margin=margin(3,4,3,5))
pa<-ggplot(al,aes(Group,Value,fill=Group))+geom_col(alpha=.85,width=.6)+geom_text(aes(label=ifelse(Metric=='Total HGT candidates',format(round(Value),big.mark=',',trim=TRUE),sprintf('%.1f',Value))),vjust=-.3,size=3,family='Arial')+facet_wrap(~Metric,scales='free_y',ncol=2)+scale_fill_manual(values=cols)+scale_y_continuous(expand=expansion(mult=c(0,.16)))+labs(x='Parasite group',y='Number of HGT candidates',title='Comparison of HGT quantity',tag='A')+facettheme
m$Group<-factor(group(m$Parasite_clade),levels=names(cols));ml<-m%>%select(Group,Length,HGT_coverage,HGT_identity,GC_Content)%>%pivot_longer(-Group,names_to='Indicator',values_to='Value')%>%filter(is.finite(Value));ml$Indicator<-factor(ml$Indicator,levels=c('Length','HGT_coverage','HGT_identity','GC_Content'),labels=c('Sequence length','HGT coverage','HGT identity','GC content (%)'))
ss<-ml%>%group_by(Indicator)%>%summarise(p=wilcox.test(Value~Group,exact=FALSE)$p.value,y=max(Value)*1.08,.groups='drop');ss$label<-ifelse(ss$p<.0001,'****',ifelse(ss$p<.001,'***',ifelse(ss$p<.01,'**',ifelse(ss$p<.05,'*','ns'))));write.table(ss,file.path(o,'data/Figure2B_restored_test_labels.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
pb<-ggplot(ml,aes(Group,Value,fill=Group))+geom_boxplot(alpha=.7,linewidth=.3,outlier.size=.35,outlier.alpha=.25)+facet_wrap(~Indicator,scales='free_y',ncol=4)+geom_text(data=ss,aes(x=1.5,y=y,label=label),inherit.aes=FALSE,size=3.1,family='Arial')+scale_fill_manual(values=cols)+scale_x_discrete(labels=c('Microbial eukaryotes'='Microbial\neukaryotes','Metazoan parasites'='Metazoan\nparasites'))+labs(x='Parasite group',y='Value',title='Sequence characteristics of HGT candidates',tag='B')+facettheme
component<-function(version,tag){z<-q[q$version==version,];z$clade<-factor(z$clade,levels=rev(c('Amoebozoa','Apicomplexa','Euglenozoa')));z$component<-factor(z$component,levels=c('family','within'),labels=c('Candidate families per species','Loci per represented candidate family'));ggplot(z,aes(x=log2_mean,y=clade,color=component,shape=component))+geom_vline(xintercept=0,linetype='dashed',color='grey55',linewidth=.3)+geom_errorbarh(aes(xmin=log2_q025,xmax=log2_q975),height=.1,position=position_dodge(width=.5),linewidth=.45)+geom_point(position=position_dodge(width=.5),size=1.7)+scale_x_continuous(breaks=0:4,labels=c(1,2,4,8,16),limits=c(-.6,4.7))+scale_color_manual(values=unname(cols),name=NULL)+scale_shape_manual(values=c(16,15),name=NULL)+labs(x='Ratio to sampled nematodes',y=NULL,title=if(version=='raw')'Candidate repertoires' else 'Relative to ordinary families',tag=tag)+th+theme(legend.position='bottom',legend.text=element_text(size=8.5),plot.title=element_text(size=9,face='bold'),axis.text.y=element_text(size=8.5),panel.grid=element_blank())}
pa<-pa+guides(fill='none');pb<-pb+guides(fill='none');p<-(pa/pb/(component('raw','C')|component('ordinary_normalized','D')))+plot_layout(heights=c(1,1.45,1.35),guides='collect')&theme(legend.position='bottom')&guides(color=guide_legend(ncol=1),shape=guide_legend(ncol=1));savep(p,'Figure2',180,225)
